1: /**
2:  * weather-card.js — dependency-free module that renders weather data into
3:  * a friendly card UI.
4:  *
5:  * Public API
6:  * ----------
7:  *  renderWeatherCard(city)              -> string   (HTML for one card)
8:  *  renderWeatherGrid(cities)            -> string   (HTML for a grid of cards)
9:  *  renderWeatherGridToElement(el, cities) -> Element|null
10:  *  injectStyles()                       -> void     (injects the card CSS, browser only)
11:  *
12:  *  Data normalization (data-fetching egg → card schema)
13:  *  ---------------------------------------------------
14:  *  mapShanghaiData(raw)                 -> object  (Open-Meteo-style raw data → card object,
15:  *                                                   includes a `daily` array for the 3-day trend)
16:  *
17:  *  `city` shape (missing fields are gracefully omitted):
18:  *   {
19:  *     city: 'Tokyo',                     // required
20:  *     country: 'JP',                     // optional
21:  *     temp: 22,                          // required
22:  *     unit: '°C',                        // optional ('C' | 'F' | '°C' | '°F'), default '°C'
23:  *     feelsLike: 20,                     // optional
24:  *     condition: 'partly-cloudy',        // code, icon name, or free text ('light rain'…)
25:  *     icon: 'cloudy',                    // alternative to `condition`
26:  *     description: 'Mostly sunny',       // optional human-readable description
27:  *     humidity: 65,                      // optional, %
28:  *     windKmh: 12,                       // optional
29:  *     windDirection: 'NW',               // optional
30:  *     high: 25, low: 17,                 // optional
31:  *     time: '14:18',                     // optional display time
32:  *     hourly: [{ time: '15:00', temp: 22, condition: 'cloudy' }]
33:  *     daily:  [{ date, label, condition, description, high, low }]   // optional, 3-day trend
34:  *   }
35:  */
36: 
37: const ICONS = {
38:   clear:           { emoji: '☀️', label: 'Sunny' },
39:   'clear-night':   { emoji: '🌙', label: 'Clear night' },
40:   'partly-cloudy': { emoji: '🌤️', label: 'Partly cloudy' },
41:   cloudy:          { emoji: '☁️', label: 'Cloudy' },
42:   overcast:        { emoji: '☁️', label: 'Overcast' },
43:   fog:             { emoji: '🌫️', label: 'Foggy' },
44:   drizzle:         { emoji: '🌦️', label: 'Drizzle' },
45:   rain:            { emoji: '🌧️', label: 'Rainy' },
46:   'heavy-rain':    { emoji: '🌧️', label: 'Heavy rain' },
47:   thunderstorm:    { emoji: '⛈️', label: 'Thunderstorm' },
48:   snow:            { emoji: '❄️', label: 'Snowy' },
49:   sleet:           { emoji: '🌨️', label: 'Sleet' },
50: };
51: 
52: const GRADIENTS = {
53:   clear:           'linear-gradient(135deg, #ffd166, #f77f00)',
54:   'clear-night':   'linear-gradient(135deg, #1e3a5f, #0d1b2a)',
55:   'partly-cloudy': 'linear-gradient(135deg, #90caf9, #4fc3f7)',
56:   cloudy:          'linear-gradient(135deg, #b0bec5, #78909c)',
57:   overcast:        'linear-gradient(135deg, #90a4ae, #546e7a)',
58:   fog:             'linear-gradient(135deg, #eceff1, #b0bec5)',
59:   drizzle:         'linear-gradient(135deg, #78909c, #546e7a)',
60:   rain:            'linear-gradient(135deg, #546e7a, #263238)',
61:   'heavy-rain':    'linear-gradient(135deg, #37474f, #1a2228)',
62:   thunderstorm:    'linear-gradient(135deg, #455a64, #1a2228)',
63:   snow:            'linear-gradient(135deg, #e0f7fa, #b2dfdb)',
64:   sleet:           'linear-gradient(135deg, #cfd8dc, #90a4ae)',
65: };
66: 
67: const LIGHT = ['clear', 'partly-cloudy', 'cloudy', 'overcast', 'fog', 'drizzle', 'snow', 'sleet'];
68: 
69: const FALLBACK = { emoji: '☁️', label: 'Weather' };
70: 
71: const KEYWORD_RULES = [
72:   { re: /thunder|lightning|storm/, name: { code: 'thunderstorm', emoji: '⛈️', label: 'Thunderstorm' } },
73:   { re: /snow|sleet/,              name: { code: 'snow', ...ICONS.snow } },
74:   { re: /rain|drizzle/,           name: { code: 'rain', ...ICONS.rain } },
75:   { re: /fog|mist|haze/,          name: { code: 'fog', ...ICONS.fog } },
76:   { re: /cloud|overcast/,         name: { code: 'cloudy', ...ICONS.cloudy } },
77:   { re: /clear|sunny|sun/,        name: { code: 'clear', ...ICONS.clear } },
78: ];
79: 
80: /**
81:  * Open-Meteo WMO weather codes → card condition codes, used to normalize
82:  * the structured data returned by the data-fetching egg.
83:  */
84: const WMO_CODE_MAP = {
85:   0: 'clear', 1: 'partly-cloudy', 2: 'partly-cloudy', 3: 'overcast',
86:   45: 'fog', 48: 'fog',
87:   51: 'drizzle', 53: 'drizzle', 55: 'drizzle',
88:   56: 'sleet', 57: 'sleet',
89:   61: 'rain', 63: 'rain', 65: 'rain',
90:   66: 'sleet', 67: 'sleet',
91:   71: 'snow', 73: 'snow', 75: 'snow', 77: 'snow',
92:   80: 'rain', 81: 'rain', 82: 'heavy-rain',
93:   85: 'snow', 86: 'snow',
94:   95: 'thunderstorm', 96: 'thunderstorm', 99: 'thunderstorm',
95: };
96: 
97: /** Chinese labels for WMO codes (used by the Shanghai card). */
98: const WMO_ZH = {
99:   0: '晴', 1: '晴', 2: '少云', 3: '多云', 45: '雾', 48: '雾',
100:   51: '毛毛雨', 53: '毛毛雨', 55: '毛毛雨', 56: '冻雨', 57: '冻雨',
101:   61: '小雨', 63: '中雨', 65: '大雨', 66: '冻雨', 67: '冻雨',
102:   71: '小雪', 73: '中雪', 75: '大雪', 77: '雪粒',
103:   80: '阵雨', 81: '中阵雨', 82: '大雨', 85: '小雪花', 86: '大雪花',
104:   95: '雷暴', 96: '雷暴', 99: '雷暴',
105: };
106: 
107: function codeToCondition(code) {
108:   const key = WMO_CODE_MAP[code];
109:   return key && ICONS[key] ? { code: key, ...ICONS[key] } : null;
110: }
111: 
112: function round1(n) {
113:   return Math.round(n * 10) / 10;
114: }
115: 
116: function extractTime(observedAt) {
117:   const m = String(observedAt ?? '').match(/T(\d{2}:\d{2})/);
118:   return m ? m[1] : null;
119: }
120: 
121: const WEEKDAY_ZH = ['一', '二', '三', '四', '五', '六', '日'];
122: 
123: function weekdayOf(dateStr) {
124:   const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(dateStr ?? ''));
125:   if (!m) return '';
126:   return WEEKDAY_ZH[new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getDay()];
127: }
128: function esc(v) {
129:   return String(v ?? '').replace(/[&<>"']/g, (ch) => ({
130:     '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
131:   }[ch]));
132: }
133: 
134: export function unitOf(city) {
135:   const u = String(city.unit ?? city.tempUnit ?? 'C').replace(/°/g, '').toUpperCase();
136:   return u === 'F' ? '°F' : '°C';
137: }
138: 
139: export function resolveCondition(city) {
140:   const raw = String(
141:     city.condition ?? city.icon ?? city.weather?.condition ?? city.weather?.icon ?? 'clear'
142:   ).toLowerCase().replace(/\s+/g, '-');
143:   if (ICONS[raw]) return { code: raw, ...ICONS[raw] };
144:   for (const rule of KEYWORD_RULES) {
145:     if (rule.re.test(raw)) return { code: rule.name.code, ...rule.name };
146:   }
147:   return { code: 'cloudy', ...FALLBACK };
148: }
149: 
150: function themeFor(code) {
151:   const light = LIGHT.includes(code);
152:   return {
153:     text: light ? '#1a202c' : '#f7fafc',
154:     chip: light ? 'rgba(255, 255, 255, 0.30)' : 'rgba(255, 255, 255, 0.14)',
155:   };
156: }
157: 
158: function statRows(city) {
159:   const rows = [
160:     { label: 'Feels like', value: city.feelsLike != null ? `${esc(city.feelsLike)}${unitOf(city)}` : null },
161:     { label: 'Humidity',   value: city.humidity   != null ? `${esc(city.humidity)}%` : null },
162:     { label: 'Wind',       value: city.windKmh    != null
163:       ? `${esc(city.windKmh)} km/h${city.windDirection ? ' ' + esc(city.windDirection) : ''}`
164:       : null },
165:     { label: 'Today',      value: city.high != null && city.low != null
166:       ? `${esc(city.high)}° / ${esc(city.low)}°` : null },
167:   ];
168:   return rows
169:     .filter((r) => r.value != null)
170:     .map((r) => `<div class="wc-stat"><span class="wc-stat-label">${r.label}</span><span class="wc-stat-value">${r.value}</span></div>`)
171:     .join('');
172: }
173: 
174: function hourlyRow(hourly, unit) {
175:   if (!Array.isArray(hourly) || hourly.length === 0) return '';
176:   const items = hourly
177:     .map((h) => {
178:       const cond = resolveCondition(h);
179:       const t = h.temp != null ? `${esc(h.temp)}${unit}` : '';
180:       return `<div class="wc-hour"><span class="wc-hour-time">${esc(h.time ?? '')}</span><span class="wc-hour-icon" aria-hidden="true">${cond.emoji}</span><span class="wc-hour-temp">${t}</span></div>`;
181:     })
182:     .join('');
183:   return `<div class="wc-hourly" aria-label="Hourly forecast">${items}</div>`;
184: }
185: 
186: export function renderWeatherCard(city) {
187:   const unit = unitOf(city);
188:   const cond = resolveCondition(city);
189:   const label = esc(city.description ?? cond.label);
190:   const theme = themeFor(cond.code);
191:   const gradient = GRADIENTS[cond.code] ?? GRADIENTS.cloudy;
192: 
193:   const sub = city.country != null
194:     ? `<span class="wc-sub">${esc(city.country)}</span>`
195:     : '';
196:   const time = city.time != null ? `<span class="wc-time">${esc(city.time)}</span>` : '';
197: 
198:   const header = `<div class="wc-header"><div class="wc-location"><span class="wc-city">${esc(city.city)}</span>${sub}</div>${time}</div>`;
199: 
200:   const main = `<div class="wc-main"><span class="wc-icon" aria-hidden="true">${cond.emoji}</span><div class="wc-temp"><span class="wc-temp-value">${esc(city.temp ?? '–')}</span><span class="wc-temp-unit">${unit}</span></div><p class="wc-condition">${label}</p></div>`;
201: 
202:   const stats = statRows(city);
203:   const hourlyHtml = hourlyRow(city.hourly, unit);
204: 
205:   return `<article class="wc" style="--wc-bg:${gradient}; --wc-text:${theme.text}; --wc-chip:${theme.chip}">${header}${main}${stats ? `<div class="wc-stats">${stats}</div>` : ''}${hourlyHtml}</article>`;
206: }
207: 
208: export function renderWeatherGrid(cities) {
209:   const list = Array.isArray(cities) ? cities : [cities];
210:   return `<div class="wc-grid" role="list">${list.map(renderWeatherCard).join('')}</div>`;
211: }
212: 
213: export function renderWeatherGridToElement(container, cities) {
214:   injectStyles();
215:   if (container) container.innerHTML = renderWeatherGrid(cities);
216:   return container;
217: }
218: 
219: const CARD_CSS = `
