226:   position: relative;
227:   border-radius: 20px;
228:   background: var(--wc-bg);
229:   color: var(--wc-text, #1a202c);
230:   padding: 16px 16px 14px;
231:   box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
232:   transition: transform 0.2s ease, box-shadow 0.2s ease;
233: }
234: .wc:hover { transform: translateY(-3px); box-shadow: 0 18px 40px rgba(0, 0, 0, 0.22); }
