243: .wc-temp-unit { font-size: 1.05rem; font-weight: 600; opacity: 0.85; margin-left: 2px; }
244: .wc-condition { margin: 0; font-size: 0.95rem; opacity: 0.9; }
245: .wc-stats {
246:   display: grid;
247:   grid-template-columns: repeat(2, 1fr);
248:   gap: 10px;
249:   padding: 10px;
250:   border-radius: 12px;
251:   background: var(--wc-chip);
252: }
253: .wc-stat { display: flex; flex-direction: column; gap: 2px; }
254: .wc-stat-label { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.05em; opacity: 0.8; }
255: .wc-stat-value { font-size: 0.95rem; font-weight: 700; }
256: .wc-hourly { display: flex; gap: 6px; margin-top: 12px; overflow-x: auto; }
257: .wc-hour {
